struct node
{
    int data;
    struct node *next;
}*first;

struct node_freq
{
    int data;
    int freq;
    struct node_freq *next;
}*head;

void create(int A[], int n)
{
    struct node *t, *last;
    first = (struct node*)malloc(sizeof(struct node));
    first->data = A[0];
    first->next = NULL;
    last = first;

    for(int i = 1 ; i < n ; i++)
    {
        t = (struct node*)malloc(sizeof(struct node));
        t->data = A[i];
        t->next = NULL;
        last->next = t;
        last = t;
    }
}

void insert(struct node_freq *p, int index, int key)
{
    struct node_freq *t = (struct node_freq *)malloc(sizeof(struct node_freq));
    t->data = key;
    t->freq = 0;

    if(index == 0)
    {
        t->next = head;
        head = t;
    }
    else
    {
        for(int i = 0 ; i < index - 1 ; i++)
        {
            p = p->next;
        }
        t->next = p->next;
        p->next = t;
    }
}

void display_freq(struct node_freq *p)
{
    while(p)
    {
        printf("Frequency of element %d is %d\n", p->data, p->freq);
        p = p->next;
    }
    printf("\n");
}

void frequency(struct node *p)
{
    struct node *q;
    int c = 0, counter;
    while(p)
    {
        counter = 0;
        q = p->next;

        while(q)
        {
            if(p->data == q->data)
            counter++;
            q = q->next;
        }
        if(counter == 0)
        {
            insert(head, c, p->data);
            c++;
        }
        p = p->next;
    }




    struct node_freq *r = head;
    while(r)
    {
        p = first;
        while(p)
        {
            if(r->data == p->data)
                r->freq++;
            p = p ->next;
        }
        r = r->next;
    }

    display_freq(head);
}

