        printf("\n1.Fixed Allocation\t2.Proportional Allocation\t3.Exit:-");
        scanf("%d",&option);
        switch(option){
            case 1: for(i=0;i<n;i++){
                        printf("\nAllocation of frames to process %c is %d",p[i],frames/n);
                    }
