typedef struct a
{
    int data;
    struct a* next;
}node;
node* createnode(int inp)
{
    node* newnode=malloc(sizeof(node));
    newnode->data=inp;
    newnode->next=NULL;
    return newnode;
}
void sequential_insert(node** head, int inp)
{
    node* linklist=createnode(inp);
    linklist->next=*head;
    *head=linklist;
    printf("%d inserted\n",(*head)->data);
}
void sorted_insert(node** head, int inp)
{
    node* newnode=createnode(inp);
    if(*head==NULL||newnode->data < (*head)->data)
    {
        newnode->next=*head;
        *head=newnode;
        printf("%d inserted\n",(*head)->data);
    }
    else
    {
        node* temp=*head;
        while(temp->next!=NULL&&temp->next->data < newnode->data)
            temp=temp->next;
        newnode->next=temp->next;
        temp->next=newnode;
        printf("%d inserted\n",temp->next->data);
    }
}
void print(node** head)
{
    if(*head==NULL)
        printf("STACK EMPTY\n");
    else
    {
        node* h=*head;
        printf("      STACK      \n");
        while(h!=NULL)
        {
            printf("\t%d\n",h->data);
            h=h->next;
        }
    }
}
