long convert(int decimalnum)
{
    long binarynum = 0;
    int rem, temp = 1;
    while (decimalnum!=0)
    {
        rem = decimalnum%2;
        decimalnum = decimalnum / 2;
        binarynum = binarynum + rem*temp;
        temp = temp * 10;
    }
    return binarynum;
}
int check(int num)
{
    long bin=convert(num);
    int last = bin%10;
    if(last==0)
        return 1;
    else
        return 2;
}
