int StrlenCap(char str[])
{
    int iCnt = 0, i = 0;

    if(str == NULL)
    {
        return -1;
    }

    while(str[i] != '\0')
    {
        if((str[i] >= 'A') && (str[i] <= 'Z'))
        {
            iCnt++;
        }

        i++;
    }

    return iCnt;
}

