void addend()
{
    struct node* temp;
    temp = (struct node*)malloc(sizeof(struct node));
    printf("Enter an element to append : ");
    scanf("%d", &temp->data);
    printf("%d inserted.\n\n", temp->data);
    temp->left = NULL;
    temp->right = NULL;
    if(root == NULL)
    {
        root = temp;
    }
    else
    {
        struct node* p = root;
        while(p->right != NULL)
        {
            p = p->right;
        }
        p->right = temp;
        temp->left = p;
    }
}

void addbegin()
{
    struct node* temp;
    temp = (struct node*)malloc(sizeof(struct node));
    printf("Enter an element to insert : ");
    scanf("%d", &temp->data);
    printf("%d inserted.\n\n", temp->data);
    temp->left = NULL;
    temp->right = NULL;
    if(root == NULL)
    {
        root = temp;
    }
    else
    {
        temp->right = root;
        root->left = temp;
        root = temp;
    }
}

void addafter()
{
    struct node* temp, *p = root, *q;
    int key, i = 1;
    printf("Enter the location where you want to insert : ");
    scanf("%d", &key);
    if(key > len)
    {
        printf("Unable to insert \n\n");
    }
    else
    {
        while(i < key)
        {
            p = p->right;
            i++;
        }
        q = p->right;
        temp = (struct node*)malloc(sizeof(struct node));
        printf("Enter an element to insert : ");
        scanf("%d", &temp->data);
        printf("%d inserted\n\n", temp->data);
        temp->left = NULL;
        temp->right = NULL;
        temp->right = q;
        q->left = temp;
        p->right = temp;
        temp->left = p;
    }
}


void display()
{
    struct node * temp = root;
    if(root == NULL)
    {
        printf("List is Empty\n\n");
    }
    else
    {
        while(temp != NULL)
        {
            printf("%d --> ", temp->data);
            temp = temp->right;
        }
        printf("\n\n");
    }
}

void reverse()
{
    struct node* temp = root;
    if(root == NULL)
    {
        printf("List is Empty\n\n");
    }
    else
    {
        while(temp->right != NULL)
        {
            temp = temp->right;
        }
        while(temp != NULL)
        {
            printf("%d --> ", temp->data);
            temp = temp->left;
        }
        printf("\n\n");
    }
}


void del()
{
    struct node* temp;
    int key, i = 1;
    printf("Enter the location of element to delete : ");
    scanf("%d", &key);
    if(key > length())
    {
        printf("Invalid Location to perform delete\n\n");
    }
    else if(key == 1)
    {
        temp = root;
        root = temp->right;
        temp->left = NULL;
        free(temp);
    }
    else if(key == length())
    {
        struct node * temp, *p;
        p = root;
        while(p->right != NULL)
        {
            p = p->right;
        }
        temp = p->left;
        temp->right = NULL;
        free(p);
    }
    else
    {
        struct node *p, *q;
        temp = root;
        while(i < key)
        {
            temp = temp->right;
            i++;
        }
        q = temp->right;
        p = temp->left;
        p->right = q;
        q->left = p;
        free(temp);
    }
}

void delvalue(int value)
{
    struct node* temp = root, *p, *q;

    if(root->data == value)
    {
        root = temp->right;
        free(temp);
    }
    else if(search(value) == 1)
    {
        while(temp->data != value)
        {
            temp = temp->right;
        }
        q = temp->right;
        p = temp->left;
        if(temp->right != NULL)
        {
            p->right = q;
            q->left = p;
            free(temp);
        }
        else
        {
            p->right = NULL;
            free(temp);
        }
    }
    else
    {
        printf("Value not found in the list.\n\n");
    }
}

void dellist()
{
    struct node *temp = root, *p;
    while(temp != NULL)
    {
        p = temp->right;
        free(temp);
        temp = p;
    }
    printf("All the elements in the list deleted successfully.\n\n");
    root = NULL;
}


int length()
{
    struct node* temp = root;
    int count = 0;
    while(temp != NULL)
    {
        count++;
        temp = temp->right;
    }
    return count;
}

int search(int value)
{
    struct node *p = root;
    while(p != NULL)
    {
        if(p->data == value)
        {
            return 1;
        }
        else
        {
            p = p->right;
        }
    }
    return 0;
}


