int SumUpperTri(int mat[][20],int r)
    {
    int i,j,sum=0;
    for(i=0;i<r;i++) 
        {
        for(j=0;j<r;j++) 
            {
            if(i<=j)
                sum=sum+mat[i][j];
            }
        }
    return sum;
    }

