void reverse()
{
    struct node *currentnode,*nextnode,*prenode;
    prenode=0;
    currentnode=nextnode=head;
    while(nextnode!=0)
    {
        nextnode=nextnode->next;
        currentnode->next=prenode;
        currentnode->pre=nextnode;
        prenode=currentnode;
        currentnode=nextnode;
    }
    head=prenode;
}
