struct Node
{
     int data;          
     struct Node *next; 
     struct Node *prev; 
};

int Traversal(struct Node *ptr)
{
     while (ptr != NULL)
     {
          printf("Element: %d\n", ptr->data);
          ptr = ptr->next;
     }
}


struct Node *insertAtFirst(struct Node *head, int data)
{
     struct Node *ptr = (struct Node *)malloc(sizeof(struct Node));
     ptr->next = head;
     ptr->data = data;
     head->prev = ptr;
     ptr->prev = NULL;
     return ptr;
};


struct Node *insertAtIndex(struct Node *head, int data, int index)
{
     struct Node *ptr = (struct Node *)malloc(sizeof(struct Node));
     struct Node *p = head;
     int i = 0;
     while (i != index - 1) 
     {
          p = p->next; 
          i++;
     }
     ptr->data = data;
     ptr->next = p->next;
     p->next = ptr;
     p->next->prev = ptr;
     ptr->prev = p;
     return head; 
};


struct Node *insertAtEnd(struct Node *head, int data)
{
     struct Node *ptr = (struct Node *)malloc(sizeof(struct Node));
     struct Node *p = head;
     while (p->next != NULL)
     {
          p = p->next;
     }
     ptr->data = data;
     p->next = ptr;
     ptr->next = NULL;
     ptr->prev = p;

     return head;
};





struct Node *deleteFirst(struct Node *head)
{
     struct Node *ptr = head;
     head = head->next;
     head->prev = NULL;
     free(ptr);
     return head;
}


struct Node *deleteInBetween(struct Node *head, int index)
{
     struct Node *p = head;
     struct Node *q = head->next;
     for (int i = 0; i < index - 1; i++)
     {
          p = p->next;
          q = q->next;
     }
     p->next = q->next;
     q->next->prev = p;
     free(q);
     return head;
}


struct Node *deleteLastNode(struct Node *head)
{
     struct Node *p = head;
     struct Node *q = head->next;
     while (q->next != NULL)
     {
          p = p->next;
          q = q->next;
     }
     p->next = NULL;
     free(q);
     return head;
}

