    i2c_Start();                        
    i2c_tx_data(0xA1);          

    i2c_rdata = i2c_rx_data();
    lcd_data(i2c_rdata);        
    i2c_rdata = i2c_rx_data();
    lcd_data(i2c_rdata);        
