    i2c_stop();

    lcd_cmd(0xC0);
    lcd_str("Data from EEPROM");
}

void i2c_init(void)
{
    PINSEL0 |= (1<<4)|(1<<6);
    PINSEL0 &= ~((1<<5)|(1<<7));        
    I2CONSET = 1<<6;                                
    I2SCLH = 75;                                        
    I2SCLL = 75;
}

void i2c_Start(void)
{
    I2CONCLR = (1<<3);      
    I2CONSET = (1<<5);          
    while(!(I2CONSET &(1<<3)));
    I2CONCLR = (1<<5);          
    I2CONCLR = (1<<3);          
}

void i2c_tx_data(char idata)
{
    I2DAT = idata;
    while(!(I2CONSET &(1<<3)));
    I2CONCLR = (1<<3);          
}

char i2c_rx_data(void)
{
    char recv_data;
    while(!(I2CONSET &(1<<3)));
    I2CONCLR = (1<<3);
    recv_data = I2DAT;
    return recv_data;
}

void i2c_stop(void)
{
    I2CONSET = (1<<4);
}
