typedef struct howto{
    int toplat;
    int tostat;
}howto;

int min;
howto fewstep(int now,int target,int* plat){
    min=-1;
    int i;
    howto ans;
    int sum;
    int toplat,tostat;
    int right,left;
    int pr,pl;
    for(i=0;i<20;i++){
        if(i-now<0){
            pr=i+1+19-now;
        }
        else{
            pr=i-now;
        }
        if(now-i<0){
            pl=i+1+19-now;
        }
        else{
            pl=now-i;
        }
        toplat= (pr<pl)? pr:-pl;
        if(target-plat[i]<0){
            right = (90-plat[i])+1+target-64;
        }
        else{
            right=target-plat[i];
        }
        if(plat[i]-target<0){
            left = plat[i]-64+1+90-target;
        }
        else{
            left=plat[i]-target;
        }
        tostat= (right<left)? right:-left;
        sum=abs(tostat)+abs(toplat);
        if(min==-1 || sum<min){
            min=sum;
            ans.toplat=toplat;
            ans.tostat=tostat;
        }
    }
    return ans;
}

