    printf("\nIngrse el numero de sumas: ");
    scanf("%i", &veces);
    double Suma_total = 0.0;
    int i=1;
    while(i <= veces){
        if(i%2 == 0)
            Suma_total += (Exp(X, i*2) / Fac(i*2));
