{
    nptr head = NULL;
    int ch, ele, key;

    printf("0. Exit      1. Insert Front      2. Insert After      3. Display\n");

    do
    {
        printf("Command: ");
        scanf("%d", &ch);

        switch(ch)
        {
            case 1: printf("Element: ");
                    scanf("%d", &ele);
                    insertFront(head, ele);
                    break;

            case 2: printf("Element and key element to insert after: ");
                    scanf("%d %d", &ele, &key);
                    insertAfter(head, ele, key);
                    break;

            case 3: display(head);
        }

    }while(ch != 0);
