#define CAPACITY 100

typedef struct
{
    char c[CAPACITY];
    int front;
    int rear;
}queue;

void enqueueright(queue *q,char n)
{
    if (q->rear == CAPACITY)
        printf("Side Full\n");

    else
        q->c[(q->rear)++]=n;
}

void enqueueleft(queue *q,char n)
{
    if (q->front==0)
        printf("Side Full\n");

    else
        q->c[--(q->front)]=n;
}

char dequeueleft(queue *q)
{
    if (q->front==q->rear)
    {
        printf("Queue Empty");
        return '\0';
    }

    else
        return q->c[(q->front)++];
}

char dequeueright(queue *q)
{
    if (q->front==q->rear)
    {
        printf("Queue Empty");
        return '\0';
    }

    else
        return q->c[--(q->rear)];
}

void display(queue *q)
{
    int i;

    for (i=q->front;i<q->rear;i++)
        printf("%c ",q->c[i]);

    printf("\n");
}

int getSize(queue *q)
{
    return q->rear - q->front;
}

