    scanf("%s", word);

    for(int i = 0 ; i < strlen(word) ; i++)
        enqueueright(&q, word[i]);


    for(int i = 0 ; i < strlen(word)/2 ; i++)
        if (dequeueleft(&q) != dequeueright(&q))
        {
            isPalin = 0;              
            break;
        }

    isPalin ? printf("YES\n") : printf("NO\n");
